'use strict';
const aftercareState={status:'pending',rule:'all',payload:null,preview:null,linkService:null};
const followupButton=(label,action,style='')=>button(label,'x-followup-'+action,style).replace('<button ','<button type="button" ');
const beforeAftercareTabs=crmTabs;crmTabs=function(){return beforeAftercareTabs().replace('</div>',`<button class="btn ${crmState.tab==='aftercare'?'primary':''}" data-action="x-followup-open" aria-pressed="${crmState.tab==='aftercare'}">Posventa</button></div>`);};
function followupMetadata(t){return `<span class="crm-beta followup-badge">Automático</span><small>${esc(t.source.label)} · ${esc(t.source.id)}</small>${t.autoClosed?`<small>Suspendido: ${esc(t.outcome||'La operación ya no requiere seguimiento.')}</small>`:''}`;}
function followupActions(t){return followupButton('Ver origen','source-'+t.id,'text')+(t.status==='pending'&&allowed('crm','editar')?followupButton('Posponer','snooze-'+t.id,'text'):'');}
const originalCrmTaskRows=crmTaskRows;crmTaskRows=function(tasks){const html=originalCrmTaskRows(tasks);if(!tasks.some(t=>t.automatic))return html;const host=document.createElement('div');host.innerHTML=html;const dateHeader=host.querySelector('thead th:nth-child(2)');if(dateHeader)dateHeader.textContent='Fecha de seguimiento';host.querySelectorAll('tbody tr').forEach((row,i)=>{const t=tasks[i];if(!t.automatic)return;row.querySelector('td').insertAdjacentHTML('beforeend',followupMetadata(t));const overdue=row.querySelector('td:nth-child(2) .badge');if(overdue)overdue.textContent='Seguimiento vencido';row.querySelector('td:last-child').insertAdjacentHTML('beforeend',followupActions(t));});return host.innerHTML;};
function aftercareRules(r){if(!r.manager||!r.aftercare.rules)return '';const editable=allowed('crm','editar');return `<details class="card crm-spacing aftercare-settings" ${Object.values(r.aftercare.rules).some(rule=>rule.enabled)?'':'open'}><summary class="card-head"><div><h2>Reglas de seguimiento</h2><small>Eventos y vencimientos desde el día de activación. Los anteriores se revisan en una vista previa.</small></div><span class="crm-beta">Configurar · recordatorios internos</span></summary><form id="aftercare-rules-form" class="card-body"><div class="aftercare-rule-grid">${Object.entries(r.aftercare.rules).map(([id,rule])=>`<section class="aftercare-rule"><label class="row"><input type="checkbox" name="${id}Enabled" value="1" ${rule.enabled?'checked':''} ${editable?'':'disabled'}><strong>${esc(rule.label)}</strong></label><p>${esc(rule.description)}</p>${input(id==='debt_due'?'Días antes del vencimiento':'Días después del evento',id+'Offset',rule.offset,'number',`required min="0" max="${rule.max}" step="1" ${editable?'':'disabled'}`)}<small>${rule.enabled?'Activa desde '+crmDate(rule.since):'Desactivada'} · ${id==='debt_due'?'Se suspende al pagar el saldo.':id==='workshop_ready'?'Solo trabajos vinculados y en estado Listo.':'Se revisa el estado de la operación antes de mantener el recordatorio.'}</small></section>`).join('')}</div><p class="muted aftercare-explanation">Pausar una regla suspende sus recordatorios pendientes. Los completados y cancelados manualmente no se vuelven a crear. Las reglas de posventa y mantenimiento se suspenden si el cliente indica que no desea contacto comercial.</p>${editable?submit('Guardar reglas de seguimiento'):''}</form></details>`;}
function aftercareView(r){const a=r.aftercare,summary=a.summary;return `<div class="kpis crm-kpis">${kpi('Seguimientos pendientes',summary.pending,'Incluidos en tu agenda',true)+kpi('Para hoy',summary.today,'Próximos contactos internos')+kpi('Vencidos',summary.overdue,'Requieren revisión')+kpi('Completados',summary.done,summary.suspended+' suspendidos automáticamente')}</div><section class="card"><div class="card-head"><div><h2>Posventa con contexto.</h2><small>Áurea prepara el recordatorio; tu equipo revisa y registra el seguimiento. No se envían mensajes.</small></div></div><form id="aftercare-filter-form" class="crm-search">${select('Estado del seguimiento','status',[['pending','Pendientes'],['done','Completados'],['cancelled','Suspendidos o cancelados'],['all','Todos']],aftercareState.status)}${select('Origen del recordatorio','rule',[['all','Todos los orígenes'],...Object.entries(a.definitions).map(([id,d])=>[id,d.label])],aftercareState.rule)}${submit('Consultar')}</form>${a.tasks.length?crmTaskRows(a.tasks):empty('Sin recordatorios en esta vista.',r.manager?'Activa las reglas de seguimiento o cambia los filtros. Puedes revisar operaciones anteriores antes de incorporarlas.':'Aquí aparecerán los recordatorios de tus clientes según las reglas activadas por administración.')}</section>${crmPager(a.total)}${aftercareRules(r)}${r.manager&&allowed('crm','editar')?`<section class="card card-body crm-spacing"><h2>Revisar operaciones anteriores</h2><p class="crm-text">Genera una vista previa por fechas antes de crear seguimientos de operaciones existentes. No se importa el historial archivado de Charles. Los recordatorios ya registrados se excluyen.</p>${followupButton('Preparar vista previa','backfill','primary')}</section>`:''}${a.unlinked.length?`<section class="card crm-spacing"><div class="card-head"><div><h2>Taller: vincular clientes</h2><small>Estos trabajos no tienen un cliente vinculado al CRM. No los asociamos por nombre automáticamente.</small></div></div>${table(['Trabajo','Cliente registrado','Estado',''],a.unlinked.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.customer)}</td><td>${esc(s.status)}</td><td>${allowed('crm','editar')&&allowed('servicios','editar')?followupButton('Vincular cliente','link-'+s.id,'text'):''}</td></tr>`))}</section>`:''}`;}
const loadBeforeAftercare=loadCrm;loadCrm=async function(){if(crmState.tab!=='aftercare'){const expected=crmState.tab;await loadBeforeAftercare();if(expected!==crmState.tab||appState.route!=='crm')return;const r=crmState.payload;if(!r)return;if(crmState.tab==='detail'){for(const t of r.detail?.tasks||[]){if(!t.automatic)continue;const edit=document.querySelector(`[data-action="x-crm-task-edit-${t.id}"]`);edit?.remove();const action=document.querySelector(`[data-action="x-crm-complete-${t.id}"],[data-action="x-crm-reopen-${t.id}"]`),row=action?.closest('tr');if(row){row.querySelector('td').insertAdjacentHTML('beforeend',followupMetadata(t));row.querySelector('td:last-child').insertAdjacentHTML('beforeend',followupActions(t));}}}if(crmState.tab==='overview'&&r.aftercare){document.querySelector('#crm-content .crm-roadmap')?.insertAdjacentHTML('beforebegin',`<section class="card card-body crm-spacing"><div class="row between"><div><h2>Posventa y seguimiento</h2><p class="crm-text">${r.aftercare.summary.pending} recordatorios automáticos pendientes, integrados en la agenda del equipo.</p></div>${followupButton('Abrir posventa','open','primary')}</div></section>`);}return;}const target=document.querySelector('#crm-content');if(!target)return;try{const r=await api('/api/crm?'+new URLSearchParams({page:crmState.page,automaticStatus:aftercareState.status,rule:aftercareState.rule}));if(!target.isConnected)return;aftercareState.payload=r;crmState.payload={...r,tasks:r.aftercare.tasks};target.innerHTML=aftercareView(r);}catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos consultar la posventa.',e.message,followupButton('Reintentar','retry'));}};
function findFollowup(id){const r=crmState.payload;return (r?.detail?.tasks||r?.tasks||[]).find(t=>t.id===id)||aftercareState.payload?.aftercare.tasks.find(t=>t.id===id);}
function backfillForm(){const lastMonth=new Date(appState.today+'T12:00:00Z');lastMonth.setUTCDate(lastMonth.getUTCDate()-30);modal('Revisar operaciones anteriores',pForm('aftercare-preview-form',input('Desde el evento o vencimiento','start',lastMonth.toISOString().slice(0,10),'date','required')+input('Hasta el evento o vencimiento','end',appState.today,'date','required')+'<p class="muted">Se usarán únicamente las reglas activas. Hasta un año y 200 recordatorios por revisión. Ventas entregadas, saldos vivos y trabajos vinculados al CRM.</p>','Generar vista previa'));}
function showAftercarePreview(p){aftercareState.preview=p;modal('Vista previa de seguimientos',pForm('aftercare-backfill-form',`<p><strong>${p.total} recordatorios nuevos</strong> · ${crmDate(p.start)} a ${crmDate(p.end)}.</p>${p.blocked?'<div class="info-strip">Hay más de 200 resultados. Reduce el rango antes de continuar.</div>':p.total?'':'<p class="muted">No hay nuevos recordatorios aplicables con estas reglas y fechas.</p>'}${p.items.length?table(['Cliente','Regla','Fecha de seguimiento'],p.items.slice(0,30).map(t=>`<tr><td>${esc(t.customer)}</td><td>${esc(t.source.label)}<small>${esc(t.source.id)}</small></td><td>${crmDate(t.dueDate)}</td></tr>`)):''}<p class="muted">${p.items.length>30?'Se muestran los primeros 30 resultados. ':''}Confirmar solo crea actividades internas; no mueve dinero ni envía mensajes.</p>`,'Crear recordatorios revisados'));if(p.blocked||!p.total)document.querySelector('#aftercare-backfill-form button[type=submit]').disabled=true;document.querySelector('#aftercare-backfill-form').insertAdjacentHTML('beforeend',followupButton('Cambiar fechas o volver a revisar','backfill','text'));}
function showLinkForm(service){aftercareState.linkService=service;modal('Vincular trabajo al cliente',pForm('aftercare-link-form',`<p>${esc(service.name)} · registrado para ${esc(service.customer)}</p><div class="commercial-catalog-search"><label class="field"><span>Buscar cliente</span><input class="input" id="aftercare-customer-query" type="search" placeholder="Nombre o documento"></label>${followupButton('Buscar clientes','customer-search')}</div><div id="aftercare-customer-results"></div><input type="hidden" name="customerId" value=""><p class="muted" id="aftercare-selected-customer">Selecciona un cliente antes de confirmar.</p>${service.status==='Entregado'?input('Fecha real de entrega (solo si se conoce)','deliveredDate','','date'):''}<p class="muted">Esta asociación queda registrada. No se interpreta el nombre del trabajo como identificación del cliente.</p>`,'Vincular cliente revisado',`data-service="${esc(service.id)}"`));}
let aftercareCustomerResults=[];
const previousFollowupAction=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-followup-'))return previousFollowupAction(a,t);const action=a.slice(11);if(action==='open'){closeModal();crmState.tab='aftercare';crmState.page=0;if(appState.route!=='crm')go('crm');else render();return;}if(action==='retry')return loadCrm();if(action==='backfill')return backfillForm();if(action.startsWith('snooze-')){const task=findFollowup(action.slice(7));return modal('Posponer seguimiento',pForm('aftercare-snooze-form',`<p>${esc(task.title)}</p>${input('Nueva fecha de seguimiento','dueDate',task.dueDate<appState.today?appState.today:task.dueDate,'date','required')}<label class="field"><span>Motivo</span><textarea name="outcome" rows="3" maxlength="1000" required></textarea></label>`,'Guardar nueva fecha',`data-id="${esc(task.id)}"`));}if(action.startsWith('source-')){const r=await api('/api/crm/followups/source?'+new URLSearchParams({id:action.slice(7)}));return modal('Origen del recordatorio',`<span class="crm-beta">${esc(r.kind)}</span><h3 class="crm-spacing">${esc(r.id)} ${esc(r.name||'')}</h3><dl class="crm-facts"><div><dt>Cliente</dt><dd>${esc(r.customer||'')}</dd></div><div><dt>Estado</dt><dd>${esc(r.status)}</dd></div><div><dt>Fecha de referencia</dt><dd>${crmDate(r.date)}</dd></div>${r.total!==undefined?`<div><dt>Total de la venta</dt><dd>${money(r.total)}</dd></div>`:''}${r.balance!==undefined?`<div><dt>Saldo actual</dt><dd>${money(r.balance)}</dd></div>`:''}${r.dueDate?`<div><dt>Vencimiento de la operación</dt><dd>${crmDate(r.dueDate)}</dd></div>`:''}</dl><p class="crm-text">${esc(r.rule)}</p>${r.reason?`<p class="crm-text">${esc(r.reason)}</p>`:''}<p class="muted">Consultar o completar el recordatorio no cambia esta operación.</p>`);}if(action.startsWith('link-')){const s=aftercareState.payload.aftercare.unlinked.find(s=>s.id===action.slice(5));return showLinkForm(s);}if(action==='customer-search'){const target=document.querySelector('#aftercare-customer-results'),r=await api('/api/crm?'+new URLSearchParams({query:document.querySelector('#aftercare-customer-query').value}));if(!target.isConnected)return;aftercareCustomerResults=r.customers;target.innerHTML=r.customers.length?r.customers.map((c,i)=>followupButton(c.name+' · '+(c.doc||'Sin documento'),'customer-pick-'+i,'text')).join(''):'<p class="muted">No encontramos clientes.</p>';return;}if(action.startsWith('customer-pick-')){const c=aftercareCustomerResults[Number(action.slice(14))];document.querySelector('#aftercare-link-form [name=customerId]').value=c.id;document.querySelector('#aftercare-selected-customer').textContent='Cliente seleccionado: '+c.name;document.querySelector('#aftercare-customer-results').innerHTML='';return;}};
const previousFollowupSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(form.id==='aftercare-filter-form'){aftercareState.status=v.status;aftercareState.rule=v.rule;crmState.page=0;render();return null;}if(form.id==='aftercare-rules-form'){const rules={};for(const id of Object.keys(aftercareState.payload.aftercare.rules))rules[id]={enabled:v[id+'Enabled']==='1',offset:Number(v[id+'Offset'])};return {command:'crm.followups.configure',body:{rules}};}if(form.id==='aftercare-preview-form'){const p=await api('/api/crm/followups/preview?'+new URLSearchParams({start:v.start,end:v.end}));showAftercarePreview(p);return null;}if(form.id==='aftercare-backfill-form'){const p=aftercareState.preview;return {command:'crm.followups.backfill',body:{start:p.start,end:p.end,digest:p.digest}};}if(form.id==='aftercare-snooze-form')return {command:'crm.followups.snooze',body:{id:form.dataset.id,dueDate:v.dueDate,outcome:v.outcome}};if(form.id==='aftercare-link-form'){if(!v.customerId)throw Error('Selecciona el cliente correcto antes de confirmar.');return {command:'crm.followups.link-service',body:{serviceId:form.dataset.service,customerId:v.customerId,deliveredDate:v.deliveredDate||''}};}return previousFollowupSubmit(form,v);};
const beforeFollowupModal=extraUI.modal;extraUI.modal=function(){beforeFollowupModal?.();const dialog=document.querySelector('#dialog');if(dialog.querySelector('#dialog-title')?.textContent==='Requieren tu atención'&&allowed('crm')){dialog.querySelector('.modal-body').insertAdjacentHTML('beforeend','<section class="card card-body crm-spacing" id="followup-notice"><h3>Posventa y seguimiento</h3><p class="muted">Consultando recordatorios…</p></section>');const target=dialog.querySelector('#followup-notice');api('/api/crm/followups/summary').then(r=>{if(target.isConnected)target.innerHTML='<h3>Posventa y seguimiento</h3><p class="crm-text">'+r.today+' para hoy · '+r.overdue+' vencidos · '+r.pending+' pendientes en total.</p>'+followupButton('Revisar seguimientos','open','primary');}).catch(()=>{if(target.isConnected)target.innerHTML='<p class="muted">Consulta tus recordatorios en CRM → Posventa.</p>';});}const form=document.querySelector('#service-form');if(!form||!allowed('crm')||!['Administrador','Superadministrador'].includes(appState.user.role))return;const service=data().services.find(s=>s.id===form.dataset.id);const customers=data().customers.filter(c=>c.active!==false||c.id===service?.customerId);if(customers.length)form.insertAdjacentHTML('afterbegin',select('Cliente vinculado al CRM (opcional)','customerId',[['','Sin vínculo con CRM'],...customers.map(c=>[c.id,c.name])],service?.customerId||''));};
document.addEventListener('change',e=>{if(e.target.name!=='customerId'||e.target.form?.id!=='service-form'||!e.target.value)return;const c=data().customers.find(c=>c.id===e.target.value);if(c)e.target.form.elements.customer.value=c.name;});
